import React, { useEffect, useRef, useState } from "react";
import { Html5QrcodeScanner } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const lastScanRef = useRef(null);

  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");

  useEffect(() => {
    const scanner = new Html5QrcodeScanner(
      "reader",
      {
        fps: 30,
        qrbox: { width: 220, height: 220 },
        rememberLastUsedCamera: true,
        aspectRatio: 1.0,
      },
      false,
    );

    scannerRef.current = scanner;

    scanner.render(
      async (decodedText) => {
        console.log("QR SCANNED:", decodedText);

        /* Prevent duplicate scan */
        if (lastScanRef.current === decodedText) return;

        lastScanRef.current = decodedText;

        try {
          const userId = decodedText;

          /* VERIFY USER */

          const verifyRes = await fetch(
            `http://localhost:5000/verify-user/${userId}`,
          );

          const verifyData = await verifyRes.json();

          if (!verifyData.success) {
            setStatus("notfound");
            setStudent(null);

            setTimeout(() => {
              lastScanRef.current = null;
            }, 2000);

            return;
          }

          setStudent(verifyData.user);

          /* MARK ATTENDANCE */

          const attendanceRes = await fetch(
            `http://localhost:5000/mark-attendance/${userId}`,
            {
              method: "PUT",
            },
          );

          const attendanceData = await attendanceRes.json();

          if (attendanceData.success) {
            setStatus("success");
          } else {
            setStatus("already");
          }
        } catch (error) {
          console.log("Scanner Error:", error);
          setStatus("servererror");
        }

        setTimeout(() => {
          lastScanRef.current = null;
        }, 3000);
      },

      (error) => {
        // ignore scan errors
      },
    );

    return () => {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(() => {});
      }
    };
  }, []);

  return (
    <div style={{ textAlign: "center", marginTop: "30px" }}>
      <h2>Admin QR Attendance Scanner</h2>

      <div
        id="reader"
        style={{
          width: "350px",
          margin: "auto",
          marginBottom: "20px",
        }}
      ></div>

      {student && (
        <div
          style={{
            border: "1px solid #ddd",
            padding: "20px",
            width: "300px",
            margin: "auto",
            borderRadius: "10px",
            background: "#f9f9f9",
          }}
        >
          <h3>{student.name}</h3>

          <p>
            <b>College:</b> {student.college_name}
          </p>

          <p>
            <b>Phone:</b> {student.phone}
          </p>

          {status === "success" && (
            <h2 style={{ color: "green" }}>✔ Attendance Marked</h2>
          )}

          {status === "already" && (
            <h2 style={{ color: "red" }}>❌ Already Scanned</h2>
          )}
        </div>
      )}

      {status === "notfound" && (
        <h2 style={{ color: "red" }}>User Not Registered</h2>
      )}

      {status === "servererror" && (
        <h2 style={{ color: "orange" }}>Server Error</h2>
      )}
    </div>
  );
}

export default QRScanner;
